data.nginx.conf:
worker_processes auto;
pid /tmp/nginx.pid;
error_log /dev/stderr warn;
events { worker_connections 1024; }
http {
    server_tokens off;
    client_body_temp_path /tmp/client_temp;
    proxy_temp_path /tmp/proxy_temp;
    fastcgi_temp_path /tmp/fastcgi_temp;
    uwsgi_temp_path /tmp/uwsgi_temp;
    scgi_temp_path /tmp/scgi_temp;
    client_max_body_size 64k;
    client_header_buffer_size 1k;
    large_client_header_buffers 2 4k;
    keepalive_timeout 15;
    map $http_x_proof_id $proof_id {
        default $request_id;
        "~^[a-zA-Z0-9-]{1,64}$" $http_x_proof_id;
    }
    # Do not log authorization, cookies, query strings, or client IP addresses.
    log_format json_access escape=json
      '{"timestamp":"$time_iso8601","request_id":"$request_id",'
      '"proof_id":"$proof_id","method":"$request_method","uri":"$uri",'
      '"status":$status,"request_time":$request_time,"bytes":$body_bytes_sent,'
      '"release":"stable","pod":"$hostname"}';
    access_log /dev/stdout json_access;
    server {
        listen 8080;
        default_type text/plain;
        add_header X-Release "stable" always;
        add_header X-Proof-ID $proof_id always;
        add_header X-Content-Type-Options nosniff always;
        location = /healthz { access_log off; return 200 "ok\n"; }
        location /missing/ {
            root /tmp/signal-no-files;
            log_not_found on;
        }
        location / { return 200 "Hello World!\n"; }
    }
    server {
        listen 127.0.0.1:8081;
        access_log off;
        location = /stub_status { stub_status; }
        location / { return 404; }
    }
}

